using UnityEngine;

public class BgmChanger : MonoBehaviour
{
	public string triggerBgmName = string.Empty;

	public bool autoDisable;

	private bool triggered;

	private string targetName = "AllyFloorContact";

	private string targetTag = "Player";

	public void OnTriggerEnter2D(Collider2D col)
	{
		if (!triggered && col.name == targetName && col.gameObject.CompareTag(targetTag))
		{
			triggered = true;
			SoundManager.PlayBGM(triggerBgmName);
			if (autoDisable)
			{
				gameObject.SetActive(value: false);
			}
		}
	}

	public void OnTriggerExit2D(Collider2D col)
	{
		if (triggered && col.name == targetName && col.gameObject.CompareTag(targetTag))
		{
			triggered = false;
		}
	}
}
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Audio;
using UnityEngine.SceneManagement;

public class SoundManager : MonoBehaviour
{
	[Serializable]
	public class SoundClip
	{
		public string audioID;

		public string prefabPath;

		public string mixerGroupPath;

		public float volume;

		public AudioClip audioClip;

		public SoundClip(string id, string prefabPath, float vol, string mixerGroup = "Master/SFX/Game")
		{
			audioID = id;
			volume = Mathf.Clamp01(vol);
			mixerGroupPath = mixerGroup;
			audioClip = ChaosBundle.GetSFX(prefabPath);
			if (audioClip == null)
			{
				Debug.Log("Missing sound file: " + id + " - " + prefabPath);
			}
		}
	}

	public class AudioWithDistVar
	{
		public string audioID;

		public Vector2 location;

		public Transform sourceTrans;

		public AudioSource audioSource;

		public int sourceIndex;

		public float overrideVolume;

		public AudioWithDistVar(string ID, Vector2 loc, Transform trans, AudioSource source, int index, float overrideVol = -1f)
		{
			audioID = ID;
			location = loc;
			sourceTrans = trans;
			audioSource = source;
			sourceIndex = index;
			overrideVolume = overrideVol;
			availableAudioSources[sourceIndex] = false;
		}
	}

	private static SoundManager instance = null;

	private static float globalClipVolumeModifier = 1f;

	public static int audioSourceCount = 50;

	public static AudioSource[] audioSources;

	public static int currentAudioSourceIndex;

	private static int nextAudioSourceIndex;

	private static Dictionary<string, SoundClip> soundClipDict;

	private static Dictionary<string, float> soundPlayedTime;

	private const float minTimeForReplay = 0.05f;

	public AudioMixer masterMixer;

	private static Dictionary<string, AudioMixerGroup> mixerGroupDict;

	public static List<AudioSource> pausedAudioSourceList;

	public static bool isPaused;

	public static AudioWithDistVar[] audioWithDistVars;

	public static bool[] availableAudioSources;

	private AudioWithDistVar audioVar;

	public static bool muteAudio = false;

	private const string gameMixerGroup = "Master/SFX/Game";

	private static readonly string uiMixerGroup = "Master/SFX/UI";

	private static readonly string bgmMixerGroup = "Master/BGM";

	private static readonly string baseResourcePath = "Assets/Sounds/";

	private string currentResourcePath = string.Empty;

	private static readonly string baseFormat = ".wav";

	private static readonly string bgmFormat = ".ogg";

	private static readonly string bgmPathStr = "Assets/Sounds/BGM/";

	private static readonly string oriPostStr = string.Empty;

	private static readonly string jazzPostStr = "_Jazz";

	private static readonly string pianoPostStr = "_Piano";

	public static BGMTrackType bgmTrack = BGMTrackType.None;

	private static AudioSource[] bgmSourceArr;

	private static GameObject bgmGameObject;

	private static bool mainBgmAudio = false;

	private static AudioSource currentBGM;

	private static AudioSource nextBGM;

	private const float bgmVolumeTransMultiplier = 0.25f;

	private static bool bgmTransInProgress = false;

	private static float bgmOriginalVol = 0.25f;

	private static float bgmJazzVol = 0.9f;

	private static float bgmPianoVol = 0.9f;

	private static AudioSource playSource;

	private static AudioSource distanceSource;

	private static AudioClip stopClip;

	private static float distanceVolume;

	private static Dictionary<string, Vector2> queuedAudioDict = new Dictionary<string, Vector2>();

	private const float standardMaxDistance = 24f;

	private static bool inBossScene;

	public static HashSet<string> bgmSet = new HashSet<string>
	{
		"PlayerRoom", "TitleScreen", "Tutorial", "Hub", "Fire", "Air", "Earth", "Lightning", "Ice", "Boss",
		"FinalBoss", "Ending", "Credits", "PlayerRoom_Jazz", "TitleScreen_Jazz", "Tutorial_Jazz", "Hub_Jazz", "Fire_Jazz", "Air_Jazz", "Earth_Jazz",
		"Lightning_Jazz", "Ice_Jazz", "Boss_Jazz", "FinalBoss_Jazz", "Ending_Jazz", "Credits_Jazz", "PlayerRoom_Piano", "TitleScreen_Piano", "Tutorial_Piano", "Hub_Piano",
		"Fire_Piano", "Air_Piano", "Earth_Piano", "Lightning_Piano", "Ice_Piano", "Boss_Piano", "FinalBoss_Piano", "Ending_Piano", "Credits_Piano"
	};

	private static List<string> missingList = new List<string>();

	private int externalClipLoadCount;

	private AudioClip externalClip;

	private List<string> externalSFXList = new List<string>();

	public static SoundManager Instance => instance;

	public static bool BGMTransitionInProgress => bgmTransInProgress || ChaosBundle.bgmLoadInProgress;

	public static float StandardPitchRange => UnityEngine.Random.Range(0.9f, 1.1f);

	public static bool BGMPaused
	{
		get
		{
			return currentBGM == null || !currentBGM.isPlaying;
		}
		set
		{
			if (!(currentBGM == null))
			{
				if (value)
				{
					currentBGM.Pause();
				}
				else
				{
					currentBGM.UnPause();
				}
			}
		}
	}

	public void Awake()
	{
		if (instance != null && instance != this)
		{
			UnityEngine.Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Initialize();
		SceneManager.sceneLoaded -= AutoPlayBGM;
		SceneManager.sceneLoaded += AutoPlayBGM;
		SceneManager.sceneLoaded -= ResetAllAudioSources;
		SceneManager.sceneLoaded += ResetAllAudioSources;
		UnityEngine.Object.DontDestroyOnLoad(gameObject);
	}

	public void Update()
	{
		for (int i = 0; i < audioSourceCount; i++)
		{
			audioVar = audioWithDistVars[i];
			if (audioVar == null)
			{
				continue;
			}
			if (audioVar.audioSource == null)
			{
				ResetSource(audioVar.sourceIndex, i);
				continue;
			}
			if (audioVar.audioSource.loop)
			{
				if (audioVar.sourceTrans == null)
				{
					audioVar.audioSource.Stop();
					ResetSource(audioVar.sourceIndex, i);
					continue;
				}
			}
			else if (!audioVar.audioSource.isPlaying)
			{
				ResetSource(audioVar.sourceIndex, i);
				continue;
			}
			audioVar.audioSource.volume = ((!(audioVar.overrideVolume >= 0f)) ? soundClipDict[audioVar.audioID].volume : audioVar.overrideVolume) * GetPercentageVolume((!(audioVar.sourceTrans == null)) ? ((Vector2)audioVar.sourceTrans.position) : audioVar.location);
		}
	}

	private void ResetSource(int sourceIndex, int distIndex)
	{
		availableAudioSources[sourceIndex] = true;
		audioWithDistVars[distIndex] = null;
	}

	private static void ResetAllAudioSources(Scene scene, LoadSceneMode loadSceneMode)
	{
		currentAudioSourceIndex = 0;
		pausedAudioSourceList.Clear();
		for (int i = 0; i < audioSourceCount; i++)
		{
			audioWithDistVars[i] = null;
			availableAudioSources[i] = true;
			if (audioSources[i] != null)
			{
				audioSources[i].Stop();
			}
		}
		inBossScene = NextLevelLoader.InBossScene(string.Empty);
	}

	public static AudioSource GetAudioSource()
	{
		currentAudioSourceIndex++;
		if (currentAudioSourceIndex == audioSourceCount)
		{
			currentAudioSourceIndex = 0;
		}
		for (int i = 0; i < audioSourceCount; i++)
		{
			nextAudioSourceIndex = (currentAudioSourceIndex + i) % audioSourceCount;
			if (availableAudioSources[nextAudioSourceIndex])
			{
				currentAudioSourceIndex = nextAudioSourceIndex;
				break;
			}
		}
		return audioSources[currentAudioSourceIndex];
	}

	public static AudioSource PlayAudio(string audioID, float pitch = 1f, bool ignoreTimeRestriction = false, float overrideVolume = -1f, float percentageVolume = -1f)
	{
		if (muteAudio)
		{
			return null;
		}
		if (!soundClipDict.ContainsKey(audioID))
		{
			return null;
		}
		if (!ignoreTimeRestriction && soundPlayedTime.ContainsKey(audioID) && Time.time - soundPlayedTime[audioID] < 0.05f)
		{
			return null;
		}
		playSource = GetAudioSource();
		if (playSource == null)
		{
			return null;
		}
		playSource.Stop();
		playSource.outputAudioMixerGroup = mixerGroupDict[soundClipDict[audioID].mixerGroupPath];
		playSource.clip = soundClipDict[audioID].audioClip;
		playSource.volume = ((overrideVolume != -1f) ? overrideVolume : soundClipDict[audioID].volume);
		if (percentageVolume != -1f)
		{
			playSource.volume *= percentageVolume;
		}
		playSource.pitch = pitch;
		playSource.Play();
		soundPlayedTime[audioID] = Time.time;
		playSource.loop = false;
		return playSource;
	}

	private IEnumerator AdjustPitchWithTimeScale(AudioSource curAudioSrc)
	{
		float originalPitch = curAudioSrc.pitch;
		while (Time.timeScale < 1f)
		{
			curAudioSrc.pitch = originalPitch * (Time.timeScale * 1.25f);
			yield return null;
		}
	}

	public static AudioSource PlayWithDistAndSPR(string givenID, Vector2 givenPosition, float pitchMod = 1f)
	{
		Vector2? soundOrigin = givenPosition;
		float overridePitch = StandardPitchRange * pitchMod;
		return PlayAudioWithDistance(givenID, soundOrigin, null, 24f, -1f, overridePitch);
	}

	public static AudioSource PlayAudioWithDistance(string audioID, Vector2? soundOrigin = null, Transform originTrans = null, float maxDistFromListener = 24f, float overrideVol = -1f, float overridePitch = 1f, bool ignoreTimeRestriction = false)
	{
		if (originTrans != null)
		{
			soundOrigin = originTrans.position;
		}
		if (!soundOrigin.HasValue)
		{
			return null;
		}
		distanceVolume = ((!inBossScene) ? GetPercentageVolume(soundOrigin.Value, maxDistFromListener) : 1f);
		if (distanceVolume <= 0f)
		{
			return null;
		}
		distanceSource = PlayAudio(audioID, overridePitch, ignoreTimeRestriction, overrideVol, distanceVolume);
		if (distanceSource == null)
		{
			return null;
		}
		audioWithDistVars[currentAudioSourceIndex] = new AudioWithDistVar(audioID, soundOrigin.Value, originTrans, distanceSource, currentAudioSourceIndex, overrideVol);
		return distanceSource;
	}

	public static void PlayAudioQueue(string audioID, Vector2 soundOrigin)
	{
		queuedAudioDict[audioID] = soundOrigin;
	}

	public static AudioSource PlayIfNotPlaying(string audioID, AudioSource givenAudio, Transform originTrans, bool useStdPitchOverride = true, float overridePitch = -1f, float overrideVolume = -1f)
	{
		if (!isPaused && originTrans != null && (givenAudio == null || !givenAudio.isPlaying))
		{
			givenAudio = PlayAudioWithDistance(audioID, null, originTrans, 24f, overrideVolume, (!useStdPitchOverride) ? overridePitch : StandardPitchRange);
			if (givenAudio != null)
			{
				givenAudio.loop = true;
			}
		}
		return givenAudio;
	}

	public static float GetPercentageVolume(Transform givenTrans, float maxDist = 24f)
	{
		return (!(givenTrans == null)) ? GetPercentageVolume(givenTrans.position, maxDist) : 1f;
	}

	public static float GetPercentageVolume(Vector2 soundOrigin, float maxDist = 24f)
	{
		return (!(soundOrigin == Vector2.zero)) ? Mathf.Clamp01(1f - Vector2.Distance(soundOrigin, CameraController.V2Position) / maxDist) : 1f;
	}

	public static void StopAudio(string audioID)
	{
		stopClip = soundClipDict[audioID].audioClip;
		for (int i = 0; i < audioSourceCount; i++)
		{
			if (audioSources[i].clip == stopClip)
			{
				audioSources[i].Stop();
			}
		}
	}

}

public static void TogglePause(bool givenStatus = true)
{
	isPaused = givenStatus;
	if (givenStatus)
	{
		for (int i = 0; i < audioSourceCount; i++)
		{
			if (audioSources[i].isPlaying)
			{
				audioSources[i].Pause();
				pausedAudioSourceList.Add(audioSources[i]);
			}
		}
		return;
	}
	foreach (AudioSource pausedAudioSource in pausedAudioSourceList)
	{
		pausedAudioSource.Play();
	}
	pausedAudioSourceList.Clear();
}

public static void PlayBGM(string givenTrackName)
{
	if (givenTrackName == "Credits")
	{
		instance.StartCoroutine(BGMTransition(givenTrackName, bgmOriginalVol));
	}
	else
	{
		HandleBGMTrack(givenTrackName);
	}
}

public static void PlayEpilogueBGM()
{
	HandleBGMTrack("Credits");
}

private static void HandleBGMTrack(string givenTrackName)
{
	switch (bgmTrack)
	{
	case BGMTrackType.Original:
		instance.StartCoroutine(BGMTransition(givenTrackName + oriPostStr, bgmOriginalVol));
		break;
	case BGMTrackType.Jazz:
		instance.StartCoroutine(BGMTransition(givenTrackName + jazzPostStr, bgmJazzVol));
		break;
	case BGMTrackType.Piano:
		instance.StartCoroutine(BGMTransition(givenTrackName + pianoPostStr, bgmPianoVol));
		break;
	}
}

private static IEnumerator BGMTransition(string givenTrackName, float givenVol = 0.25f)
{
	if (muteAudio)
	{
		yield break;
	}
	while (BGMTransitionInProgress)
	{
		yield return null;
	}
	bgmTransInProgress = true;
	if (BGMPaused)
	{
		BGMPaused = false;
	}
	if (currentBGM != null && currentBGM.isPlaying && currentBGM.clip != null && currentBGM.clip.name == givenTrackName)
	{
		bgmTransInProgress = false;
		yield break;
	}
	if (!bgmSet.Contains(givenTrackName))
	{
		if (currentBGM != null)
		{
			float tempMulti = currentBGM.volume / 0.25f * 0.25f;
			while (currentBGM.volume > 0f)
			{
				currentBGM.volume -= Time.deltaTime * tempMulti;
				yield return null;
			}
			currentBGM.volume = 0f;
			currentBGM.Stop();
		}
		bgmTransInProgress = false;
		yield break;
	}
	ChaosBundle.LoadBGM(givenTrackName);
	while (ChaosBundle.bgmLoadInProgress)
	{
		yield return null;
	}
	currentBGM = bgmSourceArr[mainBgmAudio ? 1 : 0];
	nextBGM = bgmSourceArr[(!mainBgmAudio) ? 1u : 0u];
	nextBGM.clip = ChaosBundle.GetBGM(bgmPathStr + givenTrackName + bgmFormat);
	if (currentBGM == null || !currentBGM.isPlaying)
	{
		currentBGM = nextBGM;
		if (currentBGM.clip != null)
		{
			currentBGM.volume = givenVol;
			currentBGM.Play();
			mainBgmAudio = !mainBgmAudio;
		}
		bgmTransInProgress = false;
		yield break;
	}
	nextBGM.volume = 0f;
	nextBGM.Play();
	float tempCurMulti = currentBGM.volume / 0.25f * 0.25f;
	float tempNextMulti = givenVol / 0.25f * 0.25f;
	bool tempCheck = true;
	while (tempCheck)
	{
		tempCheck = false;
		if (currentBGM.volume > 0f)
		{
			currentBGM.volume -= Time.deltaTime * tempCurMulti;
			tempCheck = true;
		}
		if (nextBGM.volume < givenVol)
		{
			nextBGM.volume += Time.deltaTime * tempNextMulti;
			tempCheck = true;
		}
		yield return null;
	}
	nextBGM.volume = givenVol;
	currentBGM.volume = 0f;
	currentBGM.Stop();
	currentBGM = nextBGM;
	bgmTransInProgress = false;
	mainBgmAudio = !mainBgmAudio;
}

private void InitializeMixerGroups()
{
	if (mixerGroupDict == null)
	{
		mixerGroupDict = new Dictionary<string, AudioMixerGroup>();
		mixerGroupDict["Master/SFX/Game"] = masterMixer.FindMatchingGroups("Master/SFX/Game")[0];
		mixerGroupDict[uiMixerGroup] = masterMixer.FindMatchingGroups(uiMixerGroup)[0];
		mixerGroupDict[bgmMixerGroup] = masterMixer.FindMatchingGroups(bgmMixerGroup)[0];
	}
}

private void Initialize()
{
	InitializeMixerGroups();
	masterMixer.FindSnapshot("Default").TransitionTo(0f);
	audioSources = new AudioSource[audioSourceCount];
	audioWithDistVars = new AudioWithDistVar[audioSourceCount];
	availableAudioSources = new bool[audioSourceCount];
	for (int i = 0; i < audioSourceCount; i++)
	{
		availableAudioSources[i] = true;
	}
	currentAudioSourceIndex = 0;
	soundClipDict = new Dictionary<string, SoundClip>();
	soundPlayedTime = new Dictionary<string, float>();
	for (int j = 0; j < audioSourceCount; j++)
	{
		audioSources[j] = gameObject.AddComponent<AudioSource>();
		audioSources[j].outputAudioMixerGroup = mixerGroupDict[uiMixerGroup];
	}
	LoadSoundClipDict();
	foreach (SoundClip value in soundClipDict.Values)
	{
		value.volume *= globalClipVolumeModifier;
	}
	if (bgmGameObject != null)
	{
		UnityEngine.Object.Destroy(bgmGameObject);
	}
	bgmGameObject = new GameObject("BgmPlayer");
	bgmGameObject.transform.SetParent(transform);
	InitBGMSettings();
	pausedAudioSourceList = new List<AudioSource>();
}

private void AddClipToDict(string newName, float newVolume = 0.25f, string newMixerGroup = "Master/SFX/Game")
{
	soundClipDict[newName] = new SoundClip(newName, currentResourcePath + newName + baseFormat, newVolume, newMixerGroup);
}

public static void InitBGMSettings()
{
	bgmTrack = (BGMTrackType)GameDataManager.gameVars.GetIntValue(GameVarsKey.BgmTrack);
	if (bgmSourceArr == null)
	{
		bgmSourceArr = new AudioSource[2];
		bgmSourceArr[0] = bgmGameObject.AddComponent<AudioSource>();
		bgmSourceArr[0].volume = 0.125f;
		bgmSourceArr[0].outputAudioMixerGroup = mixerGroupDict[bgmMixerGroup];
		bgmSourceArr[0].loop = true;
		bgmSourceArr[1] = bgmGameObject.AddComponent<AudioSource>();
		bgmSourceArr[1].volume = 0.125f;
		bgmSourceArr[1].outputAudioMixerGroup = mixerGroupDict[bgmMixerGroup];
		bgmSourceArr[1].loop = true;
	}
}

private void LoadSoundClipDict()
{
	soundClipDict.Clear();
	currentResourcePath = baseResourcePath + "Allies/";
	AddClipToDict("Artisan0");
	AddClipToDict("Artisan1");
	AddClipToDict("Banker0");
	AddClipToDict("Banker1");
	AddClipToDict("BossRush0", 0.35f);
	AddClipToDict("Collector0");
	AddClipToDict("Collector1");
	AddClipToDict("CursedMerchant0");
	AddClipToDict("Doctor0");
	AddClipToDict("Doctor1");
	AddClipToDict("Doctor2");
	AddClipToDict("Jeweler0", 0.3f);
	AddClipToDict("Looper0", 0.3f);
	AddClipToDict("Looper1", 0.3f);
	AddClipToDict("OldWizard0", 0.4f);
	AddClipToDict("OldWizard1", 0.4f);
	AddClipToDict("Shuffler0", 0.3f);
	AddClipToDict("Tailor0");
	AddClipToDict("Virtuoso0");
	currentResourcePath = baseResourcePath + "Bosses/";
	for (int i = 0; i < 4; i++)
	{
		AddClipToDict("EarthBossFlex" + i);
		AddClipToDict("EarthBossHurt" + i);
	}
	AddClipToDict("EarthBossGrunt", 0.1f);
	AddClipToDict("EarthBossHmph", 0.18f);
	AddClipToDict("FinalBossHurt0", 0.5f);
	AddClipToDict("FinalBossHurt1", 0.5f);
	AddClipToDict("FinalBossHurt2", 0.5f);
	AddClipToDict("FinalBossHurt3", 0.5f);
	AddClipToDict("FireBossHurt0", 0.5f);
	AddClipToDict("FireBossHurt1", 0.5f);
	AddClipToDict("FireBossHurt2", 0.5f);
	AddClipToDict("FireBossFlex0");
	AddClipToDict("FireBossFlex1");
