	public void AutoPlayBGM(Scene scene, LoadSceneMode loadSceneMode)
	{
		string text = scene.name;
		if (text.Contains("Boss"))
		{
			PlayBGM(string.Empty);
		}
		else if (text == "PvP")
		{
			PlayBGM("Hub");
		}
		else
		{
			PlayBGM(Application.loadedLevelName);
		}
	}

	private void OnDestroy()
	{
		SceneManager.sceneLoaded -= AutoPlayBGM;
		SceneManager.sceneLoaded -= ResetAllAudioSources;
	}

