using UnityEngine;
using UnityEngine.UI;
public class CooldownEntry
{
	private enum CooldownEntryState
	{
		Disabled,
		Ready,
		NotReady,
		Cooldown
	}
	private GameObject skillBG;
	public Image skillBorder;
	private Image skillButtonImage;
	private Image skillIcon;
	private GameObject skillBGInactive;
	private Image skillBGOverlay;
	private Player.SkillState skillState;
	private Text skillCooldownText;
	private CooldownUI cooldownUI;
	private float remainingChargeCD;
	private float remainingCD;
	private CooldownEntryState currentState;
	public CooldownEntry(Transform parentTrans, CooldownUI newCooldownUI)
	{
		cooldownUI = newCooldownUI;
		skillBG = parentTrans.Find("SkillBG").gameObject;
		skillBorder = skillBG.GetComponent<Image>();
		skillButtonImage = parentTrans.Find("SkillButton").GetComponent<Image>();
		skillIcon = parentTrans.Find("SkillIcon").GetComponent<Image>();
		skillBGInactive = parentTrans.Find("SkillBGInactive").gameObject;
		skillBGOverlay = parentTrans.Find("SkillBGOverlay").GetComponent<Image>();
		skillCooldownText = parentTrans.Find("SkillCooldown").GetComponent<Text>();
		Disable();
	}
	public void EntryUpdate()
	{
		if (currentState == CooldownEntryState.Disabled || skillState == null)
		{
			return;
		}
		if (skillState.cooldownRef.IsCharging)
		{
			if (skillState.isChargeSkill)
			{
				SetChargeCooldown();
			}
			else
			{
				SetCooldown();
			}
		}
		else if (skillState.IsReady())
		{
			SetSkillBGSprite(skillState.isSignature, skillState.IsEmpowered);
			SetReady();
		}
		else
		{
			SetNotReady();
		}
	}
	public void SetChargeCooldown()
	{
		currentState = CooldownEntryState.Cooldown;
		skillBorder.fillAmount = skillState.cooldownRef.TotalChargePercentage;
		skillBG.SetActive(value: true);
		skillBGInactive.SetActive(value: true);
		if (skillState.cooldownRef.Ready)
		{
			if (skillState.IsReady() && skillState.cooldownRef.queueCDPing)
			{
				skillState.cooldownRef.queueCDPing = false;
				cooldownUI.RequestCDPing(skillState.skillID);
			}
			if (skillState.IsReady())
			{
				skillBGOverlay.enabled = false;
				skillIcon.color = Vector4.one;
				skillButtonImage.color = CooldownUI.fullColor;
			}
			else
			{
				skillBGOverlay.enabled = true;
				skillIcon.color = CooldownUI.transparent;
				skillButtonImage.color = CooldownUI.darkened;
			}
			skillCooldownText.text = skillState.cooldownRef.chargeCount.ToString();
		}
		else
		{
			skillBGOverlay.enabled = true;
			skillIcon.color = CooldownUI.transparent;
			skillButtonImage.color = CooldownUI.darkened;
			if (skillState.cooldownRef.OnChargeDelay)
			{
				remainingChargeCD = skillState.cooldownRef.RemainingDelayTime;
				skillBGOverlay.fillAmount = remainingChargeCD / skillState.cooldownRef.chargeDelayTime;
			}
			else
			{
				remainingChargeCD = skillState.cooldownRef.RemainingTime;
				skillBGOverlay.fillAmount = remainingChargeCD / skillState.cooldownRef.MaxTime;
			}
			skillCooldownText.text = remainingChargeCD.ToString((!(remainingChargeCD < 10f)) ? "0" : "0.0");
		}
	}
	public void SetNotReady()
	{
		if (currentState != CooldownEntryState.NotReady)
		{
			skillBG.SetActive(value: false);
			skillBGInactive.SetActive(value: true);
			skillIcon.color = CooldownUI.transparent;
			skillBGOverlay.enabled = true;
			skillBGOverlay.fillAmount = 1f;
			skillCooldownText.text = string.Empty;
			skillButtonImage.color = CooldownUI.darkened;
			if (currentState == CooldownEntryState.Cooldown && skillState != null)
			{
				cooldownUI.RequestCDPing(skillState.skillID);
			}
			currentState = CooldownEntryState.NotReady;
		}
	}
	public void SetSkillBGSprite(bool isSignature, bool isEmpowered)
	{
		if (isSignature)
		{
			skillBorder.sprite = cooldownUI.skillBGSprites[4];
		}
		else if (isEmpowered)
		{
			skillBorder.sprite = cooldownUI.skillBGSprites[2];
		}
		else
		{
			skillBorder.sprite = cooldownUI.skillBGSprites[0];
		}
	}
	public void SetReady()
	{
		if (currentState != CooldownEntryState.Ready)
		{
			skillBG.SetActive(value: true);
			skillBGInactive.SetActive(value: false);
			skillIcon.color = Vector4.one;
			skillBGOverlay.enabled = false;
			skillBGOverlay.fillAmount = 0.01f;
			skillButtonImage.color = CooldownUI.fullColor;
			if (skillState.isChargeSkill)
			{
				skillBorder.fillAmount = skillState.cooldownRef.TotalChargePercentage;
				skillCooldownText.text = skillState.cooldownRef.MaxChargeCount.ToString();
			}
			else
			{
				skillCooldownText.text = string.Empty;
				skillBorder.fillAmount = 1f;
			}
			if (currentState == CooldownEntryState.Cooldown)
			{
				cooldownUI.RequestCDPing(skillState.skillID);
			}
			currentState = CooldownEntryState.Ready;
		}
	}
	public void SetCooldown()
	{
		if (currentState != CooldownEntryState.Cooldown)
		{
			SetNotReady();
			skillBGOverlay.enabled = true;
			currentState = CooldownEntryState.Cooldown;
		}
		remainingCD = skillState.cooldownRef.RemainingTime;
		if (remainingCD == 0f)
		{
			SetNotReady();
			return;
		}
		skillCooldownText.text = remainingCD.ToString((!(remainingCD < 10f)) ? "0" : "0.0");
		skillBGOverlay.fillAmount = 1f - skillState.cooldownRef.TimePercentage;
	}
	public void SetSkill(Player.SkillState newSkillState, ChaosInputDevice inputDev, int slot)
	{
		if (newSkillState == null)
		{
			skillState = null;
			Disable(forceUpdate: true);
			return;
		}
		skillState = newSkillState;
		if (skillIcon != null)
		{
			skillIcon.sprite = IconManager.GetSkillIcon(newSkillState.skillID);
		}
		if (skillButtonImage != null)
		{
			skillButtonImage.sprite = CooldownUI.GetKeySpriteFromSkillSlot(slot, inputDev);
			skillButtonImage.enabled = true;
		}
		SetSkillBGSprite(newSkillState.isSignature, newSkillState.IsEmpowered);
		SetNotReady();
	}
	public void Disable(bool forceUpdate = false)
	{
		if (forceUpdate || currentState != CooldownEntryState.Disabled)
		{
			SetNotReady();
			skillIcon.sprite = IconManager.GetSkillIcon("Disabled");
			skillButtonImage.enabled = false;
			skillCooldownText.text = string.Empty;
			currentState = CooldownEntryState.Disabled;
		}
	}
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
public class PauseMenuUI : MonoBehaviour
{
	public bool hasFocus;
	public bool paused;
	private int currentIndex;
	private int previousIndex;
	private int optionsCount;
	private bool inputReceived;
	private bool optionClicked;
	private int inputVal;
	private List<Text> pauseMenuOptions = new List<Text>();
	private bool refsFound;
	private OptionsMenu optionsMenu;
	private bool confirmationRequested;
	private bool confirmationStatus;
	private Text titleScreenText;
	private void GetOptionRefs()
	{
		Text component = transform.Find("Resume/Text").GetComponent<Text>();
		Text component2 = transform.Find("Options/Text").GetComponent<Text>();
		Text component3 = transform.Find("Quit/Text").GetComponent<Text>();
		titleScreenText = transform.Find("TitleScreen/Text").GetComponent<Text>();
		TextManager.AddUIRef("pauseMenu-title", transform.Find("Title").GetComponent<Text>());
		TextManager.AddUIRef("pauseMenu-resume", component);
		TextManager.AddUIRef("pauseMenu-titleScreen", titleScreenText);
		TextManager.AddUIRef("pauseMenu-options", component2);
		TextManager.AddUIRef("pauseMenu-quit", component3);
		pauseMenuOptions.Add(component);
		pauseMenuOptions.Add(titleScreenText);
		pauseMenuOptions.Add(component2);
		pauseMenuOptions.Add(component3);
		optionsMenu = GameController.optionsMenu;
		refsFound = true;
	}
	public void TogglePause()
	{
		if (!refsFound)
		{
			GetOptionRefs();
		}
		TextManager.AddUIRef((!Globals.IsMuseum) ? "pauseMenu-titleScreen" : "pauseMenu-skip", titleScreenText);
		paused = !paused;
		confirmationRequested = false;
		confirmationStatus = false;
		GameUI.P1Hud.SetEquipMenuAllowed(!paused);
		GameUI.P2Hud.SetEquipMenuAllowed(!paused);
		SoundManager.BGMPaused = paused;
		if (paused)
		{
			hasFocus = true;
			GameController.cameraController.blur.enabled = true;
			foreach (Text pauseMenuOption in pauseMenuOptions)
			{
				pauseMenuOption.color = Globals.uiNotSelectedColor;
			}
			optionsCount = 4;
			previousIndex = 0;
			currentIndex = 0;
			optionClicked = false;
			inputReceived = true;
			SelectOption(currentIndex);
			TimeScaleController.Pause(status: true);
			int num = -1;
			Player[] playerScripts = GameController.playerScripts;
			foreach (Player player in playerScripts)
			{
				num++;
				if (!(player == null))
				{
					player.enabled = false;
				}
			}
			return;
		}
		TimeScaleController.Pause(status: false);
		int num2 = -1;
		Player[] playerScripts2 = GameController.playerScripts;
		foreach (Player player2 in playerScripts2)
		{
			num2++;
			if (!(player2 == null))
			{
				player2.enabled = true;
			}
		}
		GameController.cameraController.blur.enabled = false;
	}
	private void OnDisable()
	{
		if (optionsMenu != null)
		{
			optionsMenu.releaseControlToParent = true;
			optionsMenu.gameObject.SetActive(value: false);
		}
		ConfirmHandlerUI.ForceQuitConfirmation();
	}
	private void Update()
	{
		if (!paused || !HandleConfirmationProgress())
		{
			return;
		}
		HandleConfirmInput();
		if (optionClicked)
		{
			switch (currentIndex)
			{
			case 0:
				TogglePause();
				gameObject.SetActive(value: false);
				break;
			case 1:
				if (!HandleConfirmationRequest())
				{
					return;
				}
				TogglePause();
				gameObject.SetActive(value: false);
				if (Globals.IsTutorial)
				{
					GameController.LoadLevel("PlayerRoom");
				}
				else
				{
					GameController.LoadLevel("TitleScreen");
				}
				break;
			case 2:
				if (!optionsMenu.gameObject.activeSelf)
				{
					optionsMenu.gameObject.SetActive(value: true);
					optionsMenu.releaseControlToParent = false;
					hasFocus = false;
					SoundManager.PlayConfirmAudio();
					break;
				}
				if (optionsMenu.releaseControlToParent)
				{
					SoundManager.BGMPaused = true;
					optionClicked = false;
					optionsMenu.gameObject.SetActive(value: false);
					hasFocus = true;
					if (GameController.resetGameDataQueued)
					{
						TogglePause();
						gameObject.SetActive(value: false);
						GameController.LoadLevel("InitialLoad");
					}
					break;
				}
				return;
			case 3:
				if (!HandleConfirmationRequest())
				{
					return;
				}
				GameController.Quit();
				break;
			}
		}
		HandleNavigation();
	}
	private void HandleConfirmInput()
	{
		if (hasFocus && (InputController.GetAnyDeviceButtonDown("Confirm") != null || Input.GetKeyDown(KeyCode.Space)))
		{
			optionClicked = true;
		}
	}
	private void HandleNavigation()
	{
		if (!hasFocus)
		{
			return;
		}
		inputVal = (InputController.GetAnyDeviceDirection(InputDirection.Down) ? 1 : (InputController.GetAnyDeviceDirection(InputDirection.Up) ? (-1) : 0));
		if (inputVal == 0)
		{
			inputReceived = false;
		}
		else if (!inputReceived)
		{
			inputReceived = true;
			previousIndex = currentIndex;
			currentIndex += inputVal;
			if (currentIndex < 0)
			{
				currentIndex = optionsCount - 1;
			}
			else if (currentIndex >= optionsCount)
			{
				currentIndex = 0;
			}
			SelectOption(currentIndex);
		}
	}
	public void SelectOption(int index)
	{
		if (hasFocus)
		{
			pauseMenuOptions[previousIndex].color = Globals.uiNotSelectedColor;
			previousIndex = index;
			currentIndex = index;
			pauseMenuOptions[index].color = Globals.uiSelectedColor;
			SoundManager.PlayAudio("MenuMove", 1f, ignoreTimeRestriction: true);
		}
	}
	public void OptionWasClicked()
	{
		if (hasFocus)
		{
			optionClicked = true;
		}
	}
	private bool HandleConfirmationRequest()
	{
		if (confirmationStatus)
		{
			return true;
		}
		ConfirmHandlerUI.RequestConfirmation();
		confirmationRequested = true;
		optionClicked = false;
		hasFocus = false;
		return false;
	}
	private bool HandleConfirmationProgress()
	{
		if (confirmationRequested)
		{
			if (ConfirmHandlerUI.RequestInProgress)
			{
				confirmationStatus = ConfirmHandlerUI.RequestConfirmation();
				return false;
			}
			confirmationRequested = false;
			optionClicked = confirmationStatus;
			hasFocus = true;
		}
		return true;
	}
}

