using System.Collections.Generic;
using UnityEngine;
public class MinimapSection : MonoBehaviour
{
	public delegate void MinimapRevealEvent(bool actual);
	private MeshRenderer meshRenderer;
	private BoxCollider2D minimapCol;
	private bool revealedByPlayer;
	public static MinimapRevealEvent minimapRevealEventHandlers;
	private static List<MinimapSection> _minimapSections;
	public static List<MinimapSection> MinimapSections
	{
		get
		{
			if (_minimapSections == null)
			{
				_minimapSections = new List<MinimapSection>();
			}
			return _minimapSections;
		}
	}
	private void Start()
	{
		meshRenderer = GetComponent<MeshRenderer>();
		minimapCol = GetComponent<BoxCollider2D>();
		MinimapSections.Add(this);
	}
	private void OnTriggerEnter2D(Collider2D col)
	{
		if (col.name == "AllyMinimapRevealer")
		{
			Reveal(collidedWithPlayer: true);
		}
	}
	public void Reveal(bool collidedWithPlayer = false)
	{
		if (meshRenderer != null && !meshRenderer.enabled)
		{
			meshRenderer.enabled = true;
			Minimap.revealedSectionCount++;
			if (minimapRevealEventHandlers != null)
			{
				minimapRevealEventHandlers(collidedWithPlayer);
			}
		}
		if (!revealedByPlayer && collidedWithPlayer)
		{
			revealedByPlayer = collidedWithPlayer;
			minimapCol.enabled = false;
		}
		if (!collidedWithPlayer && !revealedByPlayer)
		{
			meshRenderer.material.color = new Color(0.5f, 0.55f, 0.8f);
		}
		else
		{
			meshRenderer.material.color = Color.white;
		}
	}
	public void Hide(bool excludePlayerReveals = false)
	{
		if ((!excludePlayerReveals || !revealedByPlayer) && meshRenderer != null && meshRenderer.enabled)
		{
			meshRenderer.enabled = false;
			minimapCol.enabled = true;
			Minimap.revealedSectionCount--;
			if (minimapRevealEventHandlers != null)
			{
				minimapRevealEventHandlers(actual: false);
			}
		}
	}
	private void OnDestroy()
	{
		MinimapSections.Remove(this);
	}
}
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
public class MinimapFullscreen : MonoBehaviour
{
	private static MinimapFullscreen instance = null;
	public Camera minimapCamera;
	public Canvas canvas;
	private GameObject level;
	private TileGrid tileGrid;
	private Transform minimapTrans;
	private Text revealPercentageText;
	private Text floorIndicatorText;
	private Transform enemyIndicatorTrans;
	private RectTransform enemySkullsTrans;
	private Vector2 enemySkullsAnchoredPos;
	private Transform stageIndicatorTrans;
	private Image[] stageIndicators;
	public Sprite iceSprite;
	public Sprite fireSprite;
	public Sprite lightningSprite;
	public Sprite airSprite;
	public Sprite earthSprite;
	public static Vector3 stageOrigin = new Vector3(268f, -270f, -55f);
	public static Vector3 stageAvgPos = Vector3.zero;
	private static float zPosition = -55f;
	private bool inTierScene;
	private bool minimapWasEnabled = true;
	public static MinimapFullscreen Instance => instance;
	public bool IsActive => minimapCamera.enabled;
	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		minimapCamera = GetComponent<Camera>();
		Object.DontDestroyOnLoad(gameObject);
		canvas = transform.Find("TransparentBGCanvas").GetComponent<Canvas>();
		enemyIndicatorTrans = transform.Find("TransparentBGCanvas/EnemyIndicator");
		enemySkullsTrans = (RectTransform)transform.Find("TransparentBGCanvas/EnemyIndicator/Skulls");
		enemySkullsAnchoredPos = enemySkullsTrans.anchoredPosition;
		stageIndicatorTrans = transform.Find("TransparentBGCanvas/StageIndicators");
		stageIndicators = new Image[5];
		for (int i = 0; i < stageIndicators.Length; i++)
		{
			stageIndicators[i] = stageIndicatorTrans.Find("Stage" + i).GetComponent<Image>();
		}
		revealPercentageText = transform.Find("TransparentBGCanvas/RevealPercentage").GetComponent<Text>();
		floorIndicatorText = transform.Find("TransparentBGCanvas/FloorIndicator").GetComponent<Text>();
		TextManager.AddUIRef("minimap-enemyIcons", transform.Find("TransparentBGCanvas/EnemyIndicator").GetComponent<Text>());
		TextManager.AddUIRef(string.Empty, floorIndicatorText);
		TextManager.AddUIRef(string.Empty, revealPercentageText);
		zPosition = transform.position.z;
		ResetPosition();
	}
	private void ResetPosition()
	{
		if (inTierScene)
		{
			stageAvgPos = Level.AvgTileGridPosition;
			SetPosition(stageAvgPos);
		}
		else
		{
			SetPosition(stageOrigin);
		}
	}
	private void Start()
	{
		SceneManager.sceneLoaded += OnSceneLoaded;
		Disable();
	}
	private void OnDestroy()
	{
		SceneManager.sceneLoaded -= OnSceneLoaded;
	}
	public void OnSceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		if (!NextLevelLoader.InTierScene(string.Empty))
		{
			floorIndicatorText.text = string.Empty;
			floorIndicatorText.text = GameController.StageTitle;
			inTierScene = false;
			if (IsActive)
			{
				Disable();
			}
		}
		else
		{
			inTierScene = true;
			floorIndicatorText.text = GameController.StageTitle;
			ResetPosition();
		}
	}
	public void Disable()
	{
		minimapCamera.enabled = false;
		canvas.enabled = false;
		if (minimapWasEnabled && inTierScene)
		{
			GameController.minimap.Activate();
			GameController.compass.gameObject.SetActive(value: true);
		}
	}
	public void Activate()
	{
		if (!inTierScene)
		{
			SoundManager.PlayAudio("MenuError");
			return;
		}
		ResetPosition();
		GameController.compass.gameObject.SetActive(value: false);
		SetFontSize();
		UpdateStageOrder();
		minimapCamera.enabled = true;
		canvas.enabled = true;
		minimapWasEnabled = GameController.minimap.IsActive();
		GameController.minimap.Disable();
	}
	private void LateUpdate()
	{
		if (IsActive && inTierScene)
		{
			SetPosition(stageOrigin * 0.5f + (stageAvgPos + Camera.main.transform.position) * 0.25f);
		}
	}
	private void Update()
	{
		if (!inTierScene || GameController.minimap == null || LoadingScreen.loading || GameUI.pauseMenu.paused)
		{
			if (IsActive)
			{
				Disable();
			}
			return;
		}
		if (InputController.GetAnyDeviceButtonDown("Map") != null)
		{
			if (IsActive)
			{
				Disable();
			}
			else
			{
				Activate();
			}
		}
		revealPercentageText.text = Minimap.RevealedPercentage;
	}
	private void SetPosition(Vector3 givenPosition)
	{
		givenPosition.z = zPosition;
		transform.position = givenPosition;
	}
	private void UpdateStageOrder()
	{
		for (int i = 0; i < stageIndicators.Length; i++)
		{
			if (i >= GameController.MaxTierCount || i >= GameController.levelNameList.Count)
			{
				stageIndicators[i].enabled = false;
				continue;
			}
			switch (GameController.levelNameList[i])
			{
			case "Ice":
				stageIndicators[i].sprite = iceSprite;
				break;
			case "Earth":
				stageIndicators[i].sprite = earthSprite;
				break;
			case "Fire":
				stageIndicators[i].sprite = fireSprite;
				break;
			case "Air":
				stageIndicators[i].sprite = airSprite;
				break;
			case "Lightning":
				stageIndicators[i].sprite = lightningSprite;
				break;
			}
			stageIndicators[i].enabled = true;
		}
	}
	public void SetFontSize()
	{
		enemySkullsTrans.anchoredPosition = enemySkullsAnchoredPos;
		floorIndicatorText.transform.localScale = Vector3.one;
		revealPercentageText.transform.localScale = Vector3.one;
		if (TextManager.currentLanguage == ChaosLang.Spanish)
