public class SkillStoreUI : StoreUI
{
	private GameObject mainWindowPrefab;
	private MainWindow p1Window;
	private RectTransform p1RectTrans;
	private MainWindow p2Window;
	private RectTransform p2RectTrans;
	private void Awake()
	{
		mainWindowPrefab = ChaosBundle.Get("Assets/Prefabs/UI/SkillStore/MainWindow.prefab");
	}
	public override void Load(Player plyr)
	{
		base.Load(plyr);
		if (p1Window == null)
		{
			GameObject gameObject = Object.Instantiate(mainWindowPrefab, Vector3.zero, Quaternion.identity);
			gameObject.transform.SetParent(transform);
			p1RectTrans = gameObject.GetComponent<RectTransform>();
			RepositionWindow(p1RectTrans, 1);
			p1Window = gameObject.GetComponent<MainWindow>();
			p1Window.gameObject.SetActive(value: false);
		}
		if (p2Window == null)
		{
			GameObject gameObject = Object.Instantiate(mainWindowPrefab, Vector3.zero, Quaternion.identity);
			gameObject.transform.SetParent(transform);
			p2RectTrans = gameObject.GetComponent<RectTransform>();
			RepositionWindow(p2RectTrans, 2);
			p2Window = gameObject.GetComponent<MainWindow>();
			p2Window.gameObject.SetActive(value: false);
		}
		if (plyr.playerID == 0)
		{
			p1Window.gameObject.SetActive(value: true);
			p1Window.currentPlayer = GameController.playerScripts[0];
		}
		else
		{
			p2Window.gameObject.SetActive(value: true);
			p2Window.currentPlayer = GameController.playerScripts[1];
		}
	}
	private void Update()
	{
		if ((p1Window == null || !p1Window.gameObject.activeSelf) && (p2Window == null || !p2Window.gameObject.activeSelf))
		{
			gameObject.SetActive(value: false);
		}
	}
	private void RepositionWindow(RectTransform trans, int position)
	{
		Vector2 anchorMin = Vector2.zero;
		Vector2 anchorMax = Vector2.zero;
		switch (position)
		{
		case 1:
			anchorMin = Vector2.zero;
			anchorMax = new Vector2(0.5f, 1f);
			break;
		case 2:
			anchorMin = new Vector2(0.5f, 0f);
			anchorMax = Vector2.one;
			break;
		case 3:
			anchorMin = new Vector2(0.25f, 0f);
			anchorMax = new Vector2(0.75f, 1f);
			break;
		}
		trans.anchorMin = anchorMin;
		trans.anchorMax = anchorMax;
		trans.offsetMin = Vector2.zero;
		trans.offsetMax = Vector2.zero;
	}
}
