public class StoreRestock : Item
{
	public static string staticID = "StoreRestock";
	private StoreItem currentSI;
	public StoreRestock()
	{
		ID = staticID;
		category = Category.Misc;
		parentGroupID = DiscountGroupItem.staticID;
	}
	public override void Activate()
	{
		if (!GroupItemCreated(parentGroupID))
		{
			StoreItem.globalBuyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Remove(StoreItem.globalBuyEventHandlers, new StoreItem.BuyEventHandler(RestockItem));
			StoreItem.globalBuyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Combine(StoreItem.globalBuyEventHandlers, new StoreItem.BuyEventHandler(RestockItem));
		}
	}
	public override void Deactivate()
	{
		StoreItem.globalBuyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Remove(StoreItem.globalBuyEventHandlers, new StoreItem.BuyEventHandler(RestockItem));
	}
	private void RestockItem(Player player, StoreItem storeItem)
	{
		if (storeItem == null)
		{
			return;
		}
		currentSI = null;
		if (storeItem is ItemStoreItem)
		{
			ItemStoreItem itemStoreItem = (ItemStoreItem)storeItem;
			if (itemStoreItem.cursedOnly || itemStoreItem.usePlatinumCost || (itemStoreItem.disablePriceMarker && itemStoreItem.Cost == 0))
			{
				return;
			}
			UnityEngine.Object.Destroy(itemStoreItem.priceMarker.gameObject);
			currentSI = Globals.ChaosInst<StoreItem>(ItemMerchant.PrefabDict[ItemMerchant.itemPrefabName], itemStoreItem.transform.parent, itemStoreItem.transform.position);
			(currentSI as ItemStoreItem).disableMarkerOffset = itemStoreItem.disableMarkerOffset;
		}
		else if (storeItem is SkillStoreItem)
		{
			SkillStoreItem skillStoreItem = (SkillStoreItem)storeItem;
			if (skillStoreItem.usePlatinumCost || (skillStoreItem.disablePriceMarker && skillStoreItem.Cost == 0))
			{
				return;
			}
			UnityEngine.Object.Destroy(skillStoreItem.priceMarker.gameObject);
			currentSI = Globals.ChaosInst<StoreItem>(SkillStoreItem.Prefab, skillStoreItem.transform.parent, skillStoreItem.transform.position);
		}
		if (currentSI != null)
		{
			currentSI.GetComponent<SortSpriteLayer>().yValueOffset = storeItem.GetComponent<SortSpriteLayer>().yValueOffset;
			currentSI.disablePriceMarker = storeItem.disablePriceMarker;
			currentSI.priceMarkerYOffset = storeItem.priceMarkerYOffset;
		}
	}
