			tempPlayer = Player0;
			break;
		case 1:
			tempPlayer = Player1;
			break;
		default:
			tempPlayer = null;
			break;
		}
		if (tempPlayer == null || !chaosInputs.ContainsKey(tempPlayer))
		{
			return null;
		}
		if (IsControllerAssigned(controller, tempPlayer))
		{
			return null;
		}
		if (!ChaosInputDevice.lockControllerInput)
		{
			if (playerID == 0 && !GameController.coopOn && !GameController.pvpOn)
			{
				AssignAllControllersToPlayer(tempPlayer, removeFromOtherPlayers: true, controller);
