	public int controllerCount
	{
		get
		{
			if (rewiredPlayer == null || rewiredPlayer.controllers == null || rewiredPlayer.controllers.Controllers == null)
			{
				return 0;
			}
			return rewiredPlayer.controllers.joystickCount + (rewiredPlayer.controllers.hasKeyboard ? 1 : 0);
		}
	}
	public bool IsMouseAim => allowMouseAim && inputScheme == InputScheme.Keyboard;
	public bool IsMouseDash => allowMouseDash && inputScheme == InputScheme.Keyboard;
	public float GetMouseDist => ((Vector2)(Camera.main.ScreenToWorldPoint(Input.mousePosition) - player.attackOriginTrans.position)).magnitude;
	public float GetSqMouseDist => ((Vector2)(Camera.main.ScreenToWorldPoint(Input.mousePosition) - player.attackOriginTrans.position)).sqrMagnitude;
	public ChaosInputDevice(Rewired.Player rewiredPlayer, Player player = null)
	{
		this.rewiredPlayer = rewiredPlayer;
		this.player = player;
		if (player != null)
		{
			playerID = player.playerID;
		}
		else
		{
			playerID = -1;
		}
	}
	public void SetPlayer(Player player)
	{
		if (!(player == null))
		{
			this.player = player;
			playerID = player.playerID;
		}
	}
	public bool GetButtonDown(string buttonName)
	{
		if (rewiredPlayer == null)
		{
			return false;
		}
		HandleInputSchemeSwitch();
		return rewiredPlayer.GetButtonDown(buttonName);
	}
	public bool GetButtonUp(string buttonName)
	{
		if (rewiredPlayer == null)
		{
			return false;
		}
		HandleInputSchemeSwitch();
		return rewiredPlayer.GetButtonUp(buttonName);
	}
	public bool GetButton(string buttonName)
	{
		if (rewiredPlayer == null)
		{
			return false;
		}
		HandleInputSchemeSwitch();
		return rewiredPlayer.GetButton(buttonName);
	}
	public void SetPrimaryController(Controller controller)
	{
		primaryController = controller;
		if (controller.type == ControllerType.Keyboard || controller.type == ControllerType.Mouse)
		{
			inputScheme = InputScheme.Keyboard;
		}
		else
		{
			inputScheme = InputScheme.Gamepad;
		}
	}
	public Vector2 GetAimVector()
	{
		if (rewiredPlayer == null)
		{
			return Vector2.zero;
		}
		HandleInputSchemeSwitch();
		if (IsMouseAim)
		{
			return ((Vector2)(Camera.main.ScreenToWorldPoint(Input.mousePosition) - player.attackOriginTrans.position)).normalized;
		}
		curMoveVec = GetMoveVector();
		if (curMoveVec != Vector2.zero)
		{
			lastValidMoveVec = curMoveVec;
		}
		if (lockControllerAim && curMoveVec == Vector2.zero && lastValidMoveVec != Vector2.zero)
		{
			return lastValidMoveVec;
		}
		return curMoveVec;
	}
	public Vector2 GetMoveVector()
	{
		if (rewiredPlayer == null)
		{
			return Vector2.zero;
		}
		HandleInputSchemeSwitch();
		return rewiredPlayer.GetAxis2D("MoveHorizontal", "MoveVertical").normalized;
	}
	public bool DirectionWasPressed(InputDirection givenDir)
	{
		if (rewiredPlayer == null)
		{
			return false;
		}
		HandleInputSchemeSwitch();
		tempVector = rewiredPlayer.GetAxis2D("MoveHorizontal", "MoveVertical").normalized;
		return givenDir switch
		{
			InputDirection.Up => rewiredPlayer.GetButtonDown("MoveVertical"), 
			InputDirection.Down => rewiredPlayer.GetNegativeButtonDown("MoveVertical"), 
			InputDirection.Left => rewiredPlayer.GetNegativeButtonDown("MoveHorizontal"), 
			InputDirection.Right => rewiredPlayer.GetButtonDown("MoveHorizontal"), 
			_ => false, 
		};
	}
	public void HandleInputSchemeSwitch()
	{
		if (!ReInput.isReady || rewiredPlayer == null || lockControllerInput)
		{
			return;
		}
		tempController = rewiredPlayer.controllers.GetLastActiveController();
		if (tempController != null)
		{
			if (tempController.type == ControllerType.Joystick && inputScheme == InputScheme.Keyboard)
			{
				SetPrimaryController(tempController);
			}
			else if ((tempController.type == ControllerType.Keyboard || tempController.type == ControllerType.Mouse) && inputScheme == InputScheme.Gamepad)
			{
				SetPrimaryController(tempController);
			}
		}
	}
