	private bool HandleConfirmationRequest(int overrideValue = -1)
	{
		if (confirmationStatus)
		{
			return true;
		}
		ConfirmHandlerUI.RequestConfirmation((overrideValue <= -1) ? confirmCount : overrideValue);
		confirmationRequested = true;
		inputReceived = false;
		hasFocus = false;
		return false;
	}
	private bool HandleConfirmationProgress()
	{
		if (confirmationRequested)
		{
			if (ConfirmHandlerUI.RequestInProgress)
			{
				confirmationStatus = ConfirmHandlerUI.RequestConfirmation();
				return false;
			}
			confirmationRequested = false;
			if (confirmationStatus)
			{
				inputReceived = true;
			}
			else
			{
				inputReceived = false;
				ResetConfirmation();
			}
			hasFocus = true;
		}
		return true;
	}
	private void ResetConfirmation(bool resetCount = true)
	{
		hasFocus = true;
		confirmationRequested = false;
		confirmationStatus = false;
		if (resetCount)
		{
			confirmCount = 0;
