	public bool DisplayDialog(string dialogID, int overrideIndex = -1, string playerIDOverride = "", string leftIDOverride = "", string rightIDOverride = "", bool isSign = false, bool skipGhost
	{
		if (!dialogDict.ContainsKey(dialogID))
		{
			return false;
		}
		dialogDict[dialogID].CurrentIndex = overrideIndex;
		if (dialogDict[dialogID].ScriptEnd)
		{
			dialogDict[dialogID].Reset();
			return false;
		}
		DialogMessage dialogMessage = new DialogMessage(dialogDict[dialogID].GetMessage());
		if (speakerDict.ContainsKey(leftIDOverride))
		{
			dialogMessage.OverwriteSpeaker(leftIDOverride);
		}
		if (speakerDict.ContainsKey(rightIDOverride))
		{
			dialogMessage.OverwriteSpeaker(leftIDOverride, left: false);
		}
		if (dialogMessage.leftSpeakerID != null && dialogMessage.leftSpeakerID.Contains("Player"))
		{
			if (speakerDict.ContainsKey(playerIDOverride))
			{
				dialogMessage.OverwriteSpeaker(playerIDOverride);
			}
			else
			{
				if (GameController.activePlayers == null || !(GameController.activePlayers[0] != null))
				{
					return false;
				}
				dialogMessage.OverwriteSpeaker(dialogMessage.leftSpeakerID = speakerDict[GameController.activePlayers[0].skillCategory].speakerID);
			}
		}
		if (dialogMessage.rightSpeakerID != null && dialogMessage.rightSpeakerID.Contains("Player"))
		{
			if (speakerDict.ContainsKey(playerIDOverride))
			{
				dialogMessage.rightSpeakerID = playerIDOverride;
			}
			else
			{
				if (GameController.activePlayers == null || GameController.activePlayers.Length <= 0 || !(GameController.activePlayers[0] != null))
				{
					return false;
				}
				dialogMessage.rightSpeakerID = speakerDict[GameController.activePlayers[0].skillCategory].speakerID;
			}
		}
		dialogMessage.message = ParseMessage(dialogMessage);
		Activate(dialogMessage, isSign, skipGhostWriter);
		dialogInProgress = true;
		currentDialogID = dialogID;
		return true;
	}
	private string ParseMessage(DialogMessage msg)
	{
		if (msg == null || msg.message == string.Empty)
		{
			return string.Empty;
		}
		string text = msg.message;
		if (msg.LeftSpeaker != null)
		{
			string newValue = "<color=" + msg.LeftSpeaker.nameColorHex + ">" + msg.LeftSpeaker.displayName + "</color>";
			text = text.Replace(leftSpeakerString, newValue);
		}
		if (msg.RightSpeaker != null)
		{
			string newValue = "<color=" + msg.RightSpeaker.nameColorHex + ">" + msg.RightSpeaker.displayName + "</color>";
			text = text.Replace(rightSpeakerString, newValue);
		}

		}
		subStringIndexList.Clear();
		for (int num = text.IndexOf('['); num > -1; num = text.IndexOf('[', num + 1))
		{
			int num2 = text.IndexOf(']', num + 1);
			if (num2 > -1)
			{
				subStringIndexList.Add(new KeyValuePair<int, int>(num + 1, num2 - num - 1));
			}
		}
		for (int i = 0; i < subStringIndexList.Count; i++)
		{
			string text2 = text.Substring(subStringIndexList[i].Key, subStringIndexList[i].Value);
			if (speakerDict.ContainsKey(text2))
			{
				string newValue = "<color=" + speakerDict[text2].nameColorHex + ">" + speakerDict[text2].displayName + "</color>";
				text = text.Replace("[" + text2 + "]", newValue);
			}
		}
		return text;
	}
