public static void AddUIRef(string givenKey, Text givenRef, bool useSizing = true)
{
	if (givenRef == null)
	{
		Debug.Log("Text ref missing! KEY: " + givenKey);
		return;
	}
	if (!uiTextRefDict.ContainsKey(givenRef))
	{
		uiTextRefDict[givenRef] = new UITextRef(givenRef, givenKey, givenRef.fontSize, givenRef.lineSpacing, useSizing);
	}
	else
	{
		uiTextRefDict[givenRef].key = givenKey;
	}
	SetUITextFromDict(uiTextRefDict[givenRef]);
}
public static void SetUITextFromDict(Text givenRef, ChaosLang? givenLang = null)
{
