	{
		SetUITextFromDict(uiTextRefDict[givenRef], givenLang);
	}
}
private static void SetUITextFromDict(UITextRef givenUITextRef, ChaosLang? givenLang = null)
{
	if (uiTextDict == null || givenUITextRef == null || givenUITextRef.text == null)
	{
		return;
	}
	givenUITextRef.text.text = string.Empty;
	tempLang = (givenLang.HasValue ? givenLang.Value : currentLanguage);
	givenUITextRef.text.font = fontDict[tempLang].font;
	if (givenUITextRef.useSizing)
	{
		if (fontDict[tempLang].dialogMultiplier > 0f && DialogUITextRefs.Contains(givenUITextRef))
		{
			givenUITextRef.text.fontSize = (int)((float)givenUITextRef.fontSize * fontDict[tempLang].dialogMultiplier);
		}
		else if (fontDict[tempLang].spellBookMultiplier > 0f && SpellBookUITextRefs.Contains(givenUITextRef))
		{
			givenUITextRef.text.fontSize = (int)((float)givenUITextRef.fontSize * fontDict[tempLang].spellBookMultiplier);
		}
		else if (fontDict[tempLang].relicChestMultiplier > 0f && RelicChestUITextRefs.Contains(givenUITextRef))
		{
			givenUITextRef.text.fontSize = (int)((float)givenUITextRef.fontSize * fontDict[tempLang].relicChestMultiplier);
		}
		else if (fontDict[tempLang].optionsMultiplier > 0f && optionsUITextRefs.Contains(givenUITextRef))
		{
			givenUITextRef.text.fontSize = (int)((float)givenUITextRef.fontSize * fontDict[tempLang].optionsMultiplier);
		}
		else if (fontDict[tempLang].trophyMultiplier > 0f && trophyTextRefs.Contains(givenUITextRef))
		{
			givenUITextRef.text.fontSize = (int)((float)givenUITextRef.fontSize * fontDict[tempLang].trophyMultiplier);
		}
		else
		{
			givenUITextRef.text.fontSize = (int)((float)givenUITextRef.fontSize * fontDict[tempLang].multiplier);
		}
		givenUITextRef.text.lineSpacing = givenUITextRef.lineSpacing * fontDict[tempLang].lineSpacingMultiplier;
	}
