	public void HandleMenuStates()
	{
		bool flag = false;
		switch (currentState)
		{
		case TitleScreenState.Menu:
			HandleNavigation();
			break;
		case TitleScreenState.Standby:
			HandleBGChange();
			if (InputController.GetAnyDeviceButtonDown("Confirm") != null || InputController.GetAnyDeviceButtonDown("Skill0") != null || InputController.GetAnyDeviceButtonDown("Skill1") != null || InputControl
			{
