		arcana.light.enabled = false;
		arcana.bgRenderer.color = new Color(arcana.bgRenderer.color.r, arcana.bgRenderer.color.g, arcana.bgRenderer.color.b, 0.65f);
		arcana.bgRenderer.sortingLayerName = "Effect";
		arcana.bgRenderer.sortingOrder = 0;
		SpriteRenderer arcanaFlashSprite = arcana.transform.Find("FlashSprite").GetComponent<SpriteRenderer>();
		arcanaFlashSprite.sortingLayerName = "Effect";
		arcanaFlashSprite.sortingOrder = 1;
		arcana.iconRenderer.color = new Color(arcana.bgRenderer.color.r, arcana.bgRenderer.color.g, arcana.bgRenderer.color.b, 0.65f);
		arcana.iconRenderer.sortingLayerName = "Effect";
		arcana.iconRenderer.sortingOrder = 2;
		arcana.shadowRenderer.enabled = false;
		arcana.shadowRenderer.sortingLayerName = "Effect";
